import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Grok Chat","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/grok/grok-chat.md","filePath":"products/ai-coding/grok/grok-chat.md","lastUpdated":1787107158000}'),i={name:"products/ai-coding/grok/grok-chat.md"};function s(n,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="grok-chat" tabindex="-1">Grok Chat <a class="header-anchor" href="#grok-chat" aria-label="Permalink to &quot;Grok Chat&quot;">​</a></h1><blockquote><p><strong>Grok</strong> is xAI&#39;s assistant. Official definition (<a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a>): &quot;Grok is xAI&#39;s assistant, available on the web at <a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a> and in the iOS and Android apps. Sign in once and your conversations, settings, and subscription stay in sync across every platform.&quot;</p><p>This page is a product map sourced only from <a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok</a>, <a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a>, and <a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a>. It is the Claude.ai analog. It is <strong>not</strong> Grok Build — that is <a href="./grok-cli.html">grok-cli.md</a>.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Audience:</strong> frontend engineers picking a Grok surface. You need a browser or the Grok app, not a repo checkout.</p><p><strong>Goals:</strong> list what grok.com / iOS / Android actually do, how accounts sync, and where files / Voice / Imagine / Connectors live.</p><p><strong>Non-goals:</strong> a Grok Build tutorial, invented SuperGrok prices, third-party Arena Mode / 8-parallel claims, or treating Grok 4.3 as the current flagship. Coding models stay on <a href="https://docs.x.ai/developers/models" target="_blank" rel="noreferrer">developers/models</a>: <code>grok-4.6</code> and <code>grok-build-0.1</code>.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>One assistant, three official clients (<a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">overview</a>, <a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a>):</p><table tabindex="0"><thead><tr><th>Client</th><th>Official entry</th></tr></thead><tbody><tr><td>Web</td><td><a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a> — the <a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a> says use this address in Chrome/Chromium; <code>grok.x.ai</code> can miss features such as Projects</td></tr><tr><td>iOS</td><td>Grok on the App Store (<a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a>)</td></tr><tr><td>Android</td><td>Grok on Google Play (<a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a>)</td></tr><tr><td>Inside X</td><td>Grok inside X.com / X apps (the <a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a> sends X-product issues to X Help, not xAI)</td></tr></tbody></table><p>There is <strong>no official Grok desktop chat app</strong> on these pages. The desktop + iOS product with a cloud computer is <a href="./grok-bot.html">Grok Bot</a>.</p><p>Official &quot;what you can do&quot; list (<a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">overview</a>):</p><ul><li><strong>Chat</strong> — ask questions, brainstorm, write, and work through problems in a natural back-and-forth.</li><li><strong>Create images and video</strong> with Grok Imagine. Product page: <a href="./grok-imagine.html">grok-imagine.md</a>.</li><li><strong>Talk to Grok</strong> hands-free with voice. Product + API map: <a href="./grok-voice.html">grok-voice.md</a>.</li><li><strong>Upload files</strong> — PDFs, images, spreadsheets, code, audio, and more — for analysis, extraction, and summarization.</li><li><strong>Connect your tools</strong> so Grok can reach your email, files, and calendar inside a chat. See <a href="./grok-connectors.html">Connectors</a>.</li></ul><p><a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a> adds live web + 𝕏 search, deep reasoning, multi-agent mode on SuperGrok, code generation <strong>in the thread</strong>, memory across chats, canvas for long-form writing, custom instructions, and shareable conversation links. That is still chat, not a repo agent.</p><h2 id="accounts-and-subscription-sync" tabindex="-1">Accounts and subscription sync <a class="header-anchor" href="#accounts-and-subscription-sync" aria-label="Permalink to &quot;Accounts and subscription sync&quot;">​</a></h2><p>Sign in once. Conversations, settings, and the subscription stay in sync across web and the apps (<a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">overview</a>).</p><p>The <a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a> is explicit about common account traps:</p><ul><li>The subscription is tied to the <strong>account you bought it with</strong>. A web SuperGrok that does not appear in the iOS/Android app is usually a different login, not a double charge. X Premium+ only applies to the account linked to that X account.</li><li>Link X at <strong>Settings → Account → Connect your X Account</strong> on grok.com. Manage sign-in methods at <a href="https://accounts.x.ai" target="_blank" rel="noreferrer">accounts.x.ai</a>.</li><li>Apple &quot;Hide My Email&quot; subscriptions must be signed in <strong>with Apple</strong>, not the relay address via Google/email.</li><li>Delete the xAI account at <a href="https://accounts.x.ai/account" target="_blank" rel="noreferrer">accounts.x.ai/account</a>. Restorable for 30 days. API access on the same account is removed too.</li></ul><p>Billing location depends on where you subscribed (<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a>):</p><table tabindex="0"><thead><tr><th>Where you bought it</th><th>Where you manage it</th></tr></thead><tbody><tr><td>Web (grok.com)</td><td><a href="https://grok.com/?_s=billing" target="_blank" rel="noreferrer">grok.com/?_s=billing</a> or Settings → Billing</td></tr><tr><td>Apple App Store</td><td>Apple subscription / refund pages</td></tr><tr><td>Google Play</td><td>Google Play cancel; refunds via the <a href="https://accounts.x.ai/refund" target="_blank" rel="noreferrer">xAI refund form</a></td></tr><tr><td>X Premium</td><td>X, not xAI (<a href="https://help.x.com/using-x/x-premium" target="_blank" rel="noreferrer">X Help</a>)</td></tr></tbody></table><p><strong>API credits are not refundable</strong> (<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a>).</p><h2 id="plans-and-the-weekly-usage-pool" tabindex="-1">Plans and the weekly usage pool <a class="header-anchor" href="#plans-and-the-weekly-usage-pool" aria-label="Permalink to &quot;Plans and the weekly usage pool&quot;">​</a></h2><p><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">overview</a>: Grok is <strong>free to start</strong>. Paid SuperGrok plans raise limits and unlock more across every product, from <strong>one weekly usage allowance</strong> you can spend however you like.</p><p>The <a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a> (rolling out June 2026) replaces per-product daily caps:</p><ul><li>One weekly pool for Chat, Imagine, Voice, Build, and related products.</li><li>Different products cost different amounts of the pool. A chat message uses little compute; a high-quality video or a long coding task uses more.</li><li>Check <strong>Settings → Usage</strong> (web and mobile): percent used, breakdown by product (API, Build, Chat, Imagine, Voice), weekly reset time, Extra Usage Credits.</li><li>Hitting the weekly cap pauses <strong>paid</strong> features. Free-tier Chat and Voice limits remain and reset on their own schedule.</li><li>Extra Usage Credits can currently be bought <strong>on the web only</strong>, from $5, expire one year after purchase unless otherwise stated, and cost more per action than included weekly usage.</li><li>Auto Top Up is a web setting (amount + monthly cap).</li></ul><p>This page does <strong>not</strong> invent a SuperGrok dollar price or a token quota. Trust the Usage tab.</p><p>Team / Enterprise workspaces are a different product surface: <a href="./grok-business.html">Grok Business</a>.</p><h2 id="file-uploads" tabindex="-1">File uploads <a class="header-anchor" href="#file-uploads" aria-label="Permalink to &quot;File uploads&quot;">​</a></h2><p>Official path (<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a>): in any chat, click or tap <strong>+</strong> next to the input (or drag-and-drop on the web). Multiple files per message. Grok confirms a successful upload before it answers.</p><table tabindex="0"><thead><tr><th>Limit</th><th>Official number</th></tr></thead><tbody><tr><td>How many at once</td><td>Web: up to ~100. Android: up to 20. iOS: multiple files</td></tr><tr><td>Size</td><td>Most files (documents, images, code, audio): <strong>150 MB</strong> per file</td></tr><tr><td>Documents</td><td>PDF, DOCX, TXT, CSV, XLSX, PPTX, HTML, XML, JSON, MD, LaTeX, ODT, RTF, code (<code>.py</code>, <code>.cpp</code>, <code>.java</code>, <code>.html</code>, <code>.css</code>)</td></tr><tr><td>Images</td><td>JPEG/JPG, PNG, WebP, HEIC, BMP. GIF and SVG vary by platform</td></tr><tr><td>Audio</td><td>MP3, WAV, M4A, OGG, FLAC, AAC</td></tr><tr><td>Video</td><td>MP4, MOV</td></tr></tbody></table><p>What Grok does with files (<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a>): synthesis across files, transformation (summarize / rewrite), extraction (tables, quotes), analysis (charts, code, audio/video), multimodal reasoning.</p><p>Official caveats:</p><ul><li>Very long files may be summarized or handled in sections.</li><li>Embedded images inside <strong>non-PDF</strong> files may not be processed visually.</li><li>Audio/video transcription quality varies.</li><li>Manage stored assets at <a href="https://grok.com/files" target="_blank" rel="noreferrer">grok.com/files</a>. Data controls: <strong>Profile → Settings → Data Controls</strong>.</li></ul><h2 id="nearby-surfaces-do-not-mix-them" tabindex="-1">Nearby surfaces (do not mix them) <a class="header-anchor" href="#nearby-surfaces-do-not-mix-them" aria-label="Permalink to &quot;Nearby surfaces (do not mix them)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>What it is</th><th>Page</th></tr></thead><tbody><tr><td><strong>Grok Chat</strong></td><td>This page. Conversation, search, files, Voice, Imagine in-thread</td><td>grok.com / apps</td></tr><tr><td><strong>Imagine</strong></td><td>Dedicated image/video studio + Imagine API</td><td><a href="./grok-imagine.html">grok-imagine.md</a></td></tr><tr><td><strong>Voice</strong></td><td>Hands-free talk in the app + Voice API</td><td><a href="./grok-voice.html">grok-voice.md</a></td></tr><tr><td><strong>Connectors</strong></td><td>Email / files / calendar / MCP inside chat</td><td><a href="./grok-connectors.html">grok-connectors.md</a></td></tr><tr><td><strong>Build Mode</strong></td><td>Chat mode that builds a live preview and publishes to grok.me. SuperGrok Heavy Early Beta</td><td><a href="https://x.ai/grok/build-mode" target="_blank" rel="noreferrer">x.ai/grok/build-mode</a> — not Grok Build</td></tr><tr><td><strong>Grok Build</strong></td><td>Terminal coding agent (<code>grok</code>)</td><td><a href="./grok-cli.html">grok-cli.md</a></td></tr><tr><td><strong>Grok Bot</strong></td><td>Named teammates on a persistent cloud computer</td><td><a href="./grok-bot.html">grok-bot.md</a></td></tr><tr><td><strong>Grok Business</strong></td><td>Team workspaces and licenses</td><td><a href="./grok-business.html">grok-business.md</a></td></tr></tbody></table><p><a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a> product notes worth keeping:</p><ul><li><strong>Grok Studio is no longer supported.</strong> Use <strong>Grok Build</strong> instead.</li><li><strong>Companions</strong> are iOS-only. Official text: no plans to bring them to web or Android.</li></ul><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Signing in with a different Google / Apple / X identity on the phone than on the web, then assuming the subscription is missing.</li><li>Using <code>grok.x.ai</code> and wondering why Projects disappeared — official address is <strong>grok.com</strong>.</li><li>Treating in-chat code generation as a repo agent. For a real checkout, use <a href="./grok-cli.html">Grok Build</a>.</li><li>Pasting the same files every turn instead of using <a href="./grok-connectors.html">Connectors</a> for mail / Drive / calendar.</li><li>Writing third-party &quot;Grok 4.3 / 2M context&quot; as the chat flagship. Official coding guidance on <a href="https://docs.x.ai/developers/models" target="_blank" rel="noreferrer">developers/models</a>: <strong>Grok 4.6</strong>.</li></ul><h2 id="official-docs" tabindex="-1">Official docs <a class="header-anchor" href="#official-docs" aria-label="Permalink to &quot;Official docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a></td><td>What Grok is, platforms, next links</td></tr><tr><td><a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">docs.x.ai/grok/faq</a></td><td>Billing, weekly usage, files, Imagine, accounts</td></tr><tr><td><a href="https://docs.x.ai/grok/connectors" target="_blank" rel="noreferrer">docs.x.ai/grok/connectors</a></td><td>Link apps inside chat</td></tr><tr><td><a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">docs.x.ai/grok/user-guide</a></td><td>Business &amp; Enterprise workspaces</td></tr><tr><td><a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a></td><td>Marketing + store links</td></tr><tr><td><a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a></td><td>The product</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Grok learning map</a> — family decision tree</li><li><a href="./grok-imagine.html">Imagine</a> — images and video</li><li><a href="./grok-voice.html">Voice</a> — product Voice + Voice API</li><li><a href="./grok-connectors.html">Connectors</a></li><li><a href="./grok-business.html">Grok Business</a></li><li><a href="./grok-cli.html">Grok Build tutorial</a></li><li><a href="./grok-glossary.html">Glossary</a></li></ul>',42)])])}const m=t(i,[["render",s]]);export{k as __pageData,m as default};
